def flatten_dict(d):
    items = []
    for k, v in d.items():
        if isinstance(v, dict):
            if not v:
                continue
            for sub_k, sub_v in flatten_dict(v).items():
                items.append((f"{k}.{sub_k}", sub_v))
        else:
            items.append((k, v))
    return dict(items)
