class MovingAvg:
    def __init__(self, window):
        self.window = window
        self.values = []

    def push(self, x):
        self.values.append(x)
        if len(self.values) > self.window:
            self.values.pop(0)

    def mean(self):
        return sum(self.values) / len(self.values)
